// Detectar JSON ou texto vindo do node OpenAI.
// Este código tenta extrair o texto do assistant a partir de diferentes formatos
// e então tenta fazer JSON.parse. Se for JSON válido com "metric" => rota API.
// Senão => fallback (resposta direta de chat).

const raw = items[0].json;

// tenta encontrar o conteúdo do assistant em vários locais comuns
let assistantText = "";

if (raw?.choices && Array.isArray(raw.choices) && raw.choices[0]?.message?.content) {
  assistantText = raw.choices[0].message.content;
} else if (raw?.message?.content) {
  assistantText = raw.message.content;
} else if (raw?.response) {
  assistantText = raw.response;
} else if (raw?.content) {
  assistantText = raw.content;
} else if (typeof raw === 'string') {
  assistantText = raw;
} else {
  assistantText = JSON.stringify(raw);
}

assistantText = assistantText.trim();

try {
  const parsed = JSON.parse(assistantText);

  // se o JSON inclui o campo metric, consideramos intenção de API
  if (parsed && parsed.metric) {
    // garantir defaults
    parsed.limit = parsed.limit ? parseInt(parsed.limit, 10) : 5;
    parsed.order = parsed.order ? String(parsed.order).toLowerCase() : 'desc';
    parsed.attribute = parsed.attribute ? String(parsed.attribute) : 'name';

    return [{ json: { ...parsed, fallback: false } }];
  } else {
    // JSON, mas sem 'metric' -> trata como resposta de chat normal
    return [{ json: { fallback: true, reply: assistantText } }];
  }
} catch (e) {
  // não é JSON -> fallback: resposta de chat
  return [{ json: { fallback: true, reply: assistantText } }];
}

const validMetrics = ["hp", "attack", "defense", "speed", "weight"];
const { metric, limit, order, attribute } = items[0].json;

if (!validMetrics.includes(metric)) {
  return [{ json: { error: true, reply: "Esse atributo não está disponível. Escolha entre hp, attack, defense, speed, weight." } }];
}

return [{ json: { metric, limit, order, attribute } }];

